<script setup>
import { ref, onMounted, computed } from "vue";
import { state, pushLog } from "./lib/store.js";
import { serializeProfile } from "../../bbw-protocol/src/write-format.js";
import { payloadToProfile } from "./lib/decode.js";
import { gale2PayloadToProfile } from "./lib/gale2-adapter.js";
import ConnectView from "./views/ConnectView.vue";
import MappingView from "./views/MappingView.vue";
import StickView from "./views/StickView.vue";
import CurveView from "./views/CurveView.vue";
import MotionShockView from "./views/MotionShockView.vue";
import ConfigView from "./views/ConfigView.vue";
const tab=ref("dashboard"),showLog=ref(false),isReading=ref(false),theme=ref("dark");
const isGale2=computed(()=>state.profile?.deviceModel==="gale2-readonly"||state.transport?.usagePage===0xffab),profile=computed(()=>state.profile);
const TABS=[["dashboard","概览"],["connect","连接设备"],["mapping","按键映射"],["stick","扳机设置"],["curve","摇杆设置"],["motion","体感震动"],["config","配置管理"]];
const stick=side=>profile.value?.curves?.[side==="left"?0:1],deadzonePct=side=>Math.max(0,Math.min(100,Number(stick(side)?.center?.[0]??0)));
const triggerRange=side=>{const d=profile.value?.deadzone;return side==="left"?[Number(d?.c0??0),Number(d?.s0??100)]:[Number(d?.c1??0),Number(d?.s1??100)];};
const mappingKeys=computed(()=>(profile.value?.keys??[]).map((k,i)=>k?{key:k,slot:i}:null).filter(Boolean).slice(0,12));
const latestLog=computed(()=>state.log?.slice(-4).reverse()??[]);
function applyTheme(){const dark=theme.value==="dark"||(theme.value==="system"&&window.matchMedia("(prefers-color-scheme: dark)").matches);document.documentElement.classList.toggle("light",!dark)}
function setTheme(t){theme.value=t;try{localStorage.setItem("bbw-theme",t)}catch{}applyTheme()}
function cycleTheme(){setTheme(theme.value==="dark"?"light":theme.value==="light"?"system":"dark")}
onMounted(()=>{try{theme.value=localStorage.getItem("bbw-theme")||"dark"}catch{}applyTheme()});
async function doRead(){if(!state.transport||isReading.value)return;isReading.value=true;try{pushLog("读取配置…");state.payload=await state.transport.readProfile();const gale2=state.transport.lastReadIsGale2||state.transport.usagePage===0xffab;state.profile=gale2?gale2PayloadToProfile(state.payload):payloadToProfile(state.payload);state.dirty=false;pushLog(gale2?"烈风2 (只读解析模式 - 写入已安全锁定)":"读取完成,解析成功")}catch(e){pushLog("读取失败: "+e.message);console.error("Configuration read failed:",e)}finally{isReading.value=false}}
async function doWrite(){if(isGale2.value||!state.transport||!state.profile)return;if(!confirm("确认将当前编辑写入设备?"))return;try{const p=serializeProfile(state.profile,state.payload??null);await state.transport.writeProfile(p);state.payload=p;state.dirty=false;pushLog("写入完成,自动回读验证…");await doRead()}catch(e){pushLog("写入失败: "+e.message)}}
</script>
<template><div class="app-shell"><aside class="sidebar"><a class="brand" href="#" @click.prevent="tab='dashboard'"><span class="brand-mark">W</span><span><b>WON LAB</b><small>CONTROLLER STUDIO</small></span></a><div class="side-label">WORKSPACE</div><nav><button v-for="[k,label] in TABS" :key="k" class="nav-item" :class="{on:tab===k}" @click="tab=k"><span class="nav-icon">{{({dashboard:'◈',connect:'⌘',mapping:'▦',stick:'◉',curve:'⌁',motion:'✳',config:'⚙'})[k]}}</span>{{label}}<span v-if="k==='mapping'&&profile" class="nav-count">{{profile.keys.filter(Boolean).length}}</span></button></nav><div class="sidebar-bottom"><div class="side-device"><span class="device-icon">⌁</span><span><b>{{isGale2?'BIGBIG WON Gale 2':state.connected?'BIGBIG WON Controller':'No device connected'}}</b><small>{{state.connected?'DEVICE ONLINE':'NOT CONNECTED'}}</small></span><i :class="state.connected?'online':''"></i></div><small class="version">WEBHID CONFIGURATOR · BETA</small></div></aside><div class="main-area"><header class="topbar"><div class="crumb">CONTROLLER <span>/</span> {{TABS.find(x=>x[0]===tab)?.[1]}}</div><div class="top-actions"><span class="connection-pill" :class="state.connected?'connected':''"><i></i>{{state.connected?'已连接':'未连接'}}</span><span v-if="isGale2" class="protocol-pill">8-FRAME / 456B · READ ONLY</span><span v-if="state.dirty" class="dirty-pill">未保存更改</span><button class="btn top-btn" :disabled="!state.connected||isReading" @click="doRead">{{isReading?'读取中…':'读取配置'}}</button><button class="btn top-btn primary" :disabled="!state.connected||!profile||isReading||isGale2" @click="doWrite">{{isGale2?'写入已锁定':'应用更改'}}</button><button class="icon-btn" @click="cycleTheme" :title="'主题:'+theme">◐</button><button class="icon-btn" :class="{active:showLog}" @click="showLog=!showLog">☷</button></div></header><main class="content-area"><section v-if="tab==='dashboard'" class="dashboard"><div class="hero"><div><div class="eyebrow"><span class="eyebrow-dot"></span> DEVICE CONTROL CENTER</div><h1>Controller tuning<span class="accent">.</span></h1><p>Fine-tune your controller. Make every input count.</p></div><div class="hero-device"><div class="hero-glow"></div><div class="pad-art"><div class="pad-bridge"></div><div class="pad-grip left"></div><div class="pad-grip right"></div><div class="pad-stick s1"></div><div class="pad-stick s2"></div><div class="pad-dpad">✣</div><div class="pad-buttons"><i>A</i><i>B</i><i>X</i><i>Y</i></div><div class="pad-label">WON / GALE 2</div></div></div></div><div class="section-heading"><div><span class="eyebrow">LIVE PROFILE</span><h2>Controller overview</h2></div><span class="muted-text">{{profile?'Configuration loaded':'Connect your controller to get started'}}</span></div><div class="metric-grid"><article class="metric-card"><div class="metric-top"><span>CONNECTION</span><span class="metric-icon green">⌁</span></div><strong>{{state.connected?'Connected':'Offline'}}</strong><small>{{state.connected?(isGale2?'BIGBIG WON Gale 2':'BIGBIG WON Controller'):'Waiting for device'}}</small></article><article class="metric-card"><div class="metric-top"><span>PROTOCOL</span><span class="metric-icon purple">⌘</span></div><strong>{{isGale2?'8 frames':'Standard HID'}}</strong><small>{{isGale2?'456-byte profile · read only':'WebHID configuration channel'}}</small></article><article class="metric-card"><div class="metric-top"><span>BUTTON MAPPINGS</span><span class="metric-icon blue">▦</span></div><strong>{{profile?profile.keys.filter(Boolean).length:'—'}}</strong><small>Configured key slots</small></article><article class="metric-card"><div class="metric-top"><span>STICK PROFILES</span><span class="metric-icon amber">◉</span></div><strong>{{profile?profile.curves.filter(c=>c?.points?.some(v=>v!==0)).length:'—'}}<em>/ 6</em></strong><small>Curves with custom response</small></article></div><div v-if="profile" class="visual-grid"><article class="panel-card"><div class="panel-heading"><div><span class="eyebrow">INPUT RESPONSE</span><h3>Stick deadzone</h3></div><span class="live-tag">● CONFIGURED</span></div><div class="stick-visuals"><div v-for="side in ['left','right']" :key="side" class="stick-unit"><div class="radar"><div class="radar-ring r1"></div><div class="radar-ring r2"></div><div class="radar-ring r3"></div><div class="radar-cross h"></div><div class="radar-cross v"></div><div class="deadzone" :style="{width:(deadzonePct(side)*1.25+12)+'%',height:(deadzonePct(side)*1.25+12)+'%'}"></div><div class="radar-point"></div></div><div class="stick-caption"><b>{{side==='left'?'Left stick':'Right stick'}}</b><span>Center deadzone <strong>{{deadzonePct(side)}}%</strong></span></div></div></div><div class="panel-foot"><span>○ Deadzone radius</span><span>Configured center response</span></div></article><article class="panel-card"><div class="panel-heading"><div><span class="eyebrow">TRIGGER TRAVEL</span><h3>Trigger deadzones</h3></div><span class="live-tag">0—100%</span></div><div v-for="side in ['left','right']" :key="side" class="trigger-row"><div class="trigger-name"><b>{{side==='left'?'LT':'RT'}}</b><span>{{side==='left'?'Left trigger':'Right trigger'}}</span><small>{{triggerRange(side)[0]}}% — {{triggerRange(side)[1]}}%</small></div><div class="travel-track"><div class="travel-active" :style="{left:triggerRange(side)[0]+'%',width:Math.max(0,triggerRange(side)[1]-triggerRange(side)[0])+'%'}"></div><i class="travel-marker" :style="{left:triggerRange(side)[0]+'%'}"></i><i class="travel-marker end" :style="{left:triggerRange(side)[1]+'%'}"></i></div></div><div class="range-scale"><span>0</span><span>50</span><span>100</span></div></article></div><article v-if="profile" class="panel-card mapping-panel"><div class="panel-heading"><div><span class="eyebrow">QUICK ACCESS</span><h3>Active key mappings</h3></div><button class="text-button" @click="tab='mapping'">Edit mappings →</button></div><div v-if="mappingKeys.length" class="mapping-chips"><button v-for="item in mappingKeys" :key="item.slot" class="keycap" @click="tab='mapping'"><span class="keycap-face">{{item.key.code??'KEY'}}</span><small>SLOT {{String(item.slot+1).padStart(2,'0')}}</small></button></div><div v-else class="empty-state">No mappings configured yet.</div></article><article v-if="showLog" class="panel-card activity-panel"><div class="panel-heading"><div><span class="eyebrow">RECENT ACTIVITY</span><h3>Status updates</h3></div><button class="text-button" @click="state.log.splice(0,state.log.length)">Clear</button></div><p v-for="(entry,i) in latestLog" :key="i" class="activity-line"><i></i>{{entry}}</p><p v-if="!latestLog.length" class="empty-state">No recent activity.</p></article></section><ConnectView v-else-if="tab==='connect'" @read="doRead"/><MappingView v-else-if="tab==='mapping'"/><StickView v-else-if="tab==='stick'"/><CurveView v-else-if="tab==='curve'"/><MotionShockView v-else-if="tab==='motion'"/><ConfigView v-else-if="tab==='config'"/><aside v-if="showLog&&tab!=='dashboard'" class="activity-drawer"><div class="panel-heading"><h3>Recent activity</h3><button class="icon-btn" @click="showLog=false">×</button></div><p v-for="(entry,i) in latestLog" :key="i" class="activity-line">{{entry}}</p></aside></main></div></div></template>
